#!/usr/bin/env python3
"""Render docs/observability/metric-registry.md: every metric this service
emits, from two sources of truth (ported from iam-org-membership's generator).

  * The Platform Observability Registry shipped with the pinned
    platform-gincommon (internal/obsregistry/registry.json): every Tier 1
    metric owned by platform-gincommon or platform-events that this
    consume-only, database-less service can emit.
  * A real /metrics scrape (TestStandard_ProductionRegistrationOrder, which
    records a sample with every production label value on every collector
    this service owns): each Tier 3 iam_authz_enrichment_* metric with its
    type, labels, label values and help text.

Usage: metrics-inventory.py <registry.json> <scrape.txt> <gincommon-version>
Writes the Markdown to stdout. Run through `make metrics-inventory`; CI fails
when the committed file differs (.github/scripts/metricslint.sh).
"""
import json
import re
import sys

LIBRARIES = ("platform-gincommon", "platform-events")
SERVICE_PREFIX = "iam_authz_enrichment_"
# Series-level labels that are not part of a metric's own label set.
IGNORED_LABELS = {"domain", "service", "environment", "le", "quantile"}
# Library metrics registered in the registry but structurally never emitted
# here, with the reason printed in the inventory.
NOT_EMITTED = {
    "platform_messages_published_total": "consume-only (HLD §5.4)",
    "platform_outbox_pending_events": "no outbox runner",
    "platform_outbox_leased_events": "no outbox runner",
    "platform_outbox_oldest_pending_age": "no outbox runner",
    "platform_outbox_ordering_blocked_events": "no outbox runner",
    "platform_outbox_publish_attempts_total": "no outbox runner",
    "platform_duplicate_messages_total": "dedup is Valkey `SET NX`, not platform-events' inbox (LLD AE-6)",
}


def md(text):
    return (text or "").replace("|", "\\|").replace("\n", " ").strip()


def parse_scrape(path):
    """Return {family: {"type", "help", "labels": {label: {values}}}}."""
    families = {}
    for line in open(path, encoding="utf-8"):
        line = line.rstrip("\n")
        if line.startswith("# HELP "):
            name, _, help_text = line[len("# HELP "):].partition(" ")
            families.setdefault(name, {"labels": {}})["help"] = help_text
        elif line.startswith("# TYPE "):
            name, _, mtype = line[len("# TYPE "):].partition(" ")
            families.setdefault(name, {"labels": {}})["type"] = mtype
        elif line and not line.startswith("#"):
            m = re.match(r"([a-zA-Z_:][a-zA-Z0-9_:]*)(\{([^}]*)\})?", line)
            if not m:
                continue
            series = family = m.group(1)
            for suffix in ("_bucket", "_sum", "_count"):
                if series.endswith(suffix) and series[: -len(suffix)] in families:
                    family = series[: -len(suffix)]
            fam = families.setdefault(family, {"labels": {}})
            for label, value in re.findall(r'([a-zA-Z_][a-zA-Z0-9_]*)="([^"]*)"', m.group(3) or ""):
                if label not in IGNORED_LABELS:
                    fam["labels"].setdefault(label, set()).add(value)
    return families


def labels_cell(entry):
    labels = entry.get("labels") or []
    if not labels:
        return "-"
    cell = ", ".join(f"`{label}`" for label in labels)
    for label, values in sorted((entry.get("label_values") or {}).items()):
        cell += f"<br>`{label}` ∈ " + ", ".join(f"`{v}`" for v in values)
    return cell


def type_cell(entry):
    if entry.get("type") == "histogram" and entry.get("buckets"):
        return f"histogram ({entry['buckets']})"
    return entry.get("type", "")


def main():
    registry_path, scrape_path, gincommon_version = sys.argv[1:4]
    entries = json.load(open(registry_path, encoding="utf-8"))["metrics"]
    scrape = parse_scrape(scrape_path)

    out = []
    w = out.append
    w("# Metric inventory: iam-authz-enrichment")
    w("")
    w("<!-- Generated by `make metrics-inventory` (.github/scripts/metrics-inventory.py) from the")
    w(f"     Platform Observability Registry in platform-gincommon {gincommon_version} and a real /metrics")
    w("     scrape of this service. Do not edit; CI fails when this file is out of date. -->")
    w("")
    w("Every series carries the centrally injected const labels `domain` (`iam`), `service` "
      "(`iam-authz-enrichment`) and `environment`. The tables list each metric's own labels only. "
      "Status is the registry's: `approved`, or `proposed` (awaiting ratification by observability "
      "governance). Tier 3 metrics belong to this service and need no registry entry. "
      "See [README.md](README.md) for how the tiers are built and enforced.")
    w("")

    w("## Tier 1: platform-shared metrics (emitted by the platform libraries)")
    w("")
    w("This service constructs none of these; the libraries record them on the shared registry "
      "(`gincommon.MetricsRegisterer()`). A label vector appears on the scrape only once it has a "
      "sample, so for example `platform_messages_*` show up only after a consumer receives its "
      "first message, and `platform_grpc_panics_total` only after a recovered panic.")
    w("")
    w("Notes specific to this service:")
    w("")
    w("- `platform_grpc_*` carry all of Envoy's ext_authz traffic. A deny is a successful RPC (`grpc_code=\"OK\"`).")
    w("- `platform_http_*` cover only `/healthz`, `/readyz` and the AsyncAPI viewer. There is no business HTTP API.")
    w("- `platform_dlq_messages_total` counts each poison message platform-events forwards to a queue's DLQ "
      "(`operation=\"consume\"`; LLD §16 AE-36).")
    w("- `platform_queue_depth` / `platform_dlq_depth` are sampled only when `SQS_QUEUE_DEPTH_INTERVAL` is set (unset by default).")
    w("- `platform_outbox_errors_total` / `platform_outbox_dead_letter_operations_total` are registered by "
      "`events.InitMetrics` but never incremented, because this service runs no outbox.")
    w("")
    w("| Metric | Emitted by | Type | Status | Labels | Meaning |")
    w("|---|---|---|---|---|---|")
    for entry in entries:
        if entry.get("tier") != "platform" or entry.get("owner") not in LIBRARIES or entry["name"] in NOT_EMITTED:
            continue
        w(f"| `{entry['name']}` | {entry['owner']} | {type_cell(entry)} | {entry.get('status', '')} "
          f"| {labels_cell(entry)} | {md(entry.get('help'))} |")
    w("")
    w("Registered but **not emitted** by this service: "
      + "; ".join(f"`{name}` ({why})" for name, why in NOT_EMITTED.items())
      + "; and every platform-pgcommon `platform_db_*` metric (no database, HLD §5.4).")
    w("")

    w("## Tier 2: IAM domain-shared metrics")
    w("")
    domain = [e["name"] for e in entries if e.get("tier") == "domain"]
    emitted = [n for n in domain if n in scrape]
    if emitted:
        sys.exit(f"Tier 2 metrics now emitted ({emitted}) — extend metrics-inventory.py with a Tier 2 table")
    w("None. The registry's `iam_*` metrics (" + ", ".join(f"`{n}`" for n in domain) + ") describe "
      "identity, RLS and lifecycle concerns this stateless decision point doesn't have.")
    w("")

    w(f"## Tier 3: service-specific metrics (`{SERVICE_PREFIX}*`)")
    w("")
    w("Built in `internal/adapter/outbound/metrics/recorder.go`. All latency histograms use 16 "
      "exponential buckets from 0.5 ms (factor 2, up to ~16 s). Label values are every value the "
      "service records.")
    w("")
    w("| Metric | Type | Labels | Meaning |")
    w("|---|---|---|---|")
    for name in sorted(n for n in scrape if n.startswith(SERVICE_PREFIX)):
        fam = scrape[name]
        labels = fam["labels"]
        cell = ", ".join(f"`{label}`" for label in sorted(labels)) or "-"
        for label in sorted(labels):
            cell += f"<br>`{label}` ∈ " + ", ".join(f"`{v}`" for v in sorted(labels[label]))
        w(f"| `{name}` | {fam.get('type', '')} | {cell} | {md(fam.get('help'))} |")
    w("")
    w("The cache hit ratios are exposed as hits/lookups counter pairs, never a server-computed ratio "
      "gauge, so they aggregate correctly across replicas and time windows.")
    print("\n".join(out))


if __name__ == "__main__":
    main()
